&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Bryntum&lt;/td&gt;
&lt;td&gt;848 ms&lt;/td&gt;
&lt;td&gt;2,945 ms&lt;/td&gt;
&lt;td&gt;5,710 ms&lt;/td&gt;
&lt;td&gt;32,226 ms&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Kendo&lt;/td&gt;
&lt;td&gt;4,350 ms&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Syncfusion&lt;/td&gt;
&lt;td&gt;141 ms&lt;/td&gt;
&lt;td&gt;449 ms&lt;/td&gt;
&lt;td&gt;1,153 ms&lt;/td&gt;
&lt;td&gt;error&lt;/td&gt;
